@layer components {
  /* ---------------------------------------------------------------- */
  /* Label                                                            */
  /* ---------------------------------------------------------------- */

  [data-slot="autocomplete-label"] {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 4px;
    min-height: 16px;
    margin: 0;
    padding: 0;
    font-style: normal;
    font-weight: 530;
    font-size: 13px;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
    color: var(--v2-text-text-base);
    font-variation-settings: "slnt" 0;
    cursor: default;
    user-select: none;
  }

  [data-slot="autocomplete-label"][data-disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* ---------------------------------------------------------------- */
  /* Control wrapper (mirrors input.css input-group)                  */
  /* ---------------------------------------------------------------- */

  [data-slot="autocomplete-control"] {
    box-sizing: border-box;
    display: flex;
    flex-direction: row;
    align-items: center;
    padding-block: 0;
    padding-inline: 0 4px;
    gap: 4px;
    width: 280px;
    max-width: 100%;
    height: 28px;
    border: 0;
    border-radius: 6px;
    outline: 1px solid transparent;
    outline-offset: -1px;
    background: var(--v2-background-bg-base);
    box-shadow: var(--v2-elevation-input);
    flex: none;
    align-self: stretch;
    transition:
      background 85ms ease-out,
      outline-color 85ms ease-out,
      box-shadow 85ms ease-out;
  }

  [data-slot="autocomplete-control"][data-appearance="small"] {
    height: 24px;
  }

  [data-slot="autocomplete-control"][data-appearance="large"] {
    height: 32px;
    padding-inline: 0 6px;
  }

  [data-slot="autocomplete-control"][data-surface="layer-1"] {
    background: var(--v2-background-bg-layer-01);
  }

  [data-slot="autocomplete-control"][data-surface="invisible"] {
    background: transparent;
    box-shadow: none;
  }

  @media (hover: hover) {
    [data-slot="autocomplete-control"]:hover:not(
        [data-disabled],
        [data-invalid],
        [data-surface="invisible"]
      ):not(:has([data-slot="autocomplete-input"][data-disabled])):not(
        :has([data-slot="autocomplete-input"]:focus)
      ) {
      box-shadow:
        inset 0 0 0 100vmax var(--v2-overlay-simple-overlay-hover),
        var(--v2-elevation-input);
    }

    [data-slot="autocomplete-control"][data-surface="invisible"]:hover:not(
        [data-disabled],
        [data-invalid]
      ):not(:has([data-slot="autocomplete-input"][data-disabled])):not(
        :has([data-slot="autocomplete-input"]:focus)
      ) {
      background: var(--v2-overlay-simple-overlay-hover);
    }
  }

  [data-slot="autocomplete-control"]:has([data-slot="autocomplete-input"]:focus):not(
      [data-disabled],
      [data-invalid]
    ):not(:has([data-slot="autocomplete-input"][data-disabled])) {
    outline-color: var(--v2-border-border-focus);
    box-shadow: none;
  }

  [data-slot="autocomplete-control"][data-invalid]:not([data-disabled]):not(
      :has([data-slot="autocomplete-input"][data-disabled])
    ) {
    outline-color: var(--v2-state-fg-danger);
    box-shadow: none;
  }

  [data-slot="autocomplete-control"]:is(
      [data-disabled],
      :has([data-slot="autocomplete-input"][data-disabled])
    ) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  [data-slot="autocomplete-control"] > [data-slot="autocomplete-leading-icon"] {
    display: flex;
    flex: none;
    align-items: center;
    justify-content: center;
    padding-inline-start: 8px;
    margin-inline-end: 2px;
    color: var(--v2-icon-icon-muted);
    pointer-events: none;
  }

  [data-slot="autocomplete-control"] > [data-slot="autocomplete-leading-icon"] svg {
    display: block;
    flex: none;
    width: 14px;
    height: 14px;
  }

  /* ---------------------------------------------------------------- */
  /* Input (inside control or standalone)                             */
  /* ---------------------------------------------------------------- */

  [data-slot="autocomplete-control"] [data-slot="autocomplete-input"] {
    display: block;
    width: 100%;
    min-width: 0;
    flex: 1 1 auto;
    min-height: 0;
    height: 100%;
    padding-block: 0;
    padding-inline: 8px 4px;
    margin: 0;
    border: 0;
    background: transparent;
    outline: none;
    font-style: normal;
    font-weight: 440;
    font-size: 13px;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
    color: var(--v2-text-text-base);
    font-variation-settings: "slnt" 0;
  }

  [data-slot="autocomplete-control"][data-leading-icon] [data-slot="autocomplete-input"] {
    padding-inline-start: 0;
  }

  [data-slot="autocomplete-control"][data-invalid]:not([data-disabled])
    [data-slot="autocomplete-input"] {
    color: var(--v2-state-fg-danger);
    caret-color: var(--v2-state-fg-danger);
  }

  [data-slot="autocomplete-control"][data-invalid]:not([data-disabled])
    [data-slot="autocomplete-input"]::placeholder {
    color: var(--v2-state-fg-danger);
    opacity: 1;
  }

  /* Standalone input without AutocompleteControl */
  [data-slot="autocomplete-input"]:not(
      [data-slot="autocomplete-control"] [data-slot="autocomplete-input"]
    ) {
    box-sizing: border-box;
    display: block;
    width: 280px;
    max-width: 100%;
    height: 28px;
    padding: 0 8px;
    margin: 0;
    border: 0;
    border-radius: 6px;
    outline: 1px solid transparent;
    outline-offset: -1px;
    background: var(--v2-background-bg-base);
    box-shadow: var(--v2-elevation-input);
    font-style: normal;
    font-weight: 440;
    font-size: 13px;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
    color: var(--v2-text-text-base);
    font-variation-settings: "slnt" 0;
    transition:
      background 85ms ease-out,
      outline-color 85ms ease-out,
      box-shadow 85ms ease-out;
  }

  @media (hover: hover) {
    [data-slot="autocomplete-input"]:not(
        [data-slot="autocomplete-control"] [data-slot="autocomplete-input"]
      ):hover:not([data-disabled], [data-invalid]):not(:focus) {
      box-shadow:
        inset 0 0 0 100vmax var(--v2-overlay-simple-overlay-hover),
        var(--v2-elevation-input);
    }
  }

  [data-slot="autocomplete-input"]:not(
      [data-slot="autocomplete-control"] [data-slot="autocomplete-input"]
    ):focus:not([data-disabled], [data-invalid]) {
    outline-color: var(--v2-border-border-focus);
    box-shadow: none;
  }

  [data-slot="autocomplete-input"]:not(
      [data-slot="autocomplete-control"] [data-slot="autocomplete-input"]
    )[data-invalid]:not([data-disabled]) {
    outline-color: var(--v2-state-fg-danger);
    box-shadow: none;
    color: var(--v2-state-fg-danger);
  }

  [data-slot="autocomplete-input"]:not(
      [data-slot="autocomplete-control"] [data-slot="autocomplete-input"]
    )[data-disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  [data-slot="autocomplete-input"]::placeholder {
    color: var(--v2-text-text-faint);
    user-select: none;
  }

  [data-slot="autocomplete-input"][type="search"]::-webkit-search-cancel-button {
    -webkit-appearance: none;
    appearance: none;
    display: none;
  }

  /* ---------------------------------------------------------------- */
  /* Clear & Trigger icon buttons                                     */
  /* ---------------------------------------------------------------- */

  [data-slot="autocomplete-clear"],
  [data-slot="autocomplete-trigger"] {
    display: inline-flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    align-self: center;
    flex: none;
    width: 20px;
    height: 20px;
    padding: 2px;
    border: 0;
    border-radius: 4px;
    background: transparent;
    color: var(--v2-icon-icon-muted);
    cursor: pointer;
    outline: none;
    transition: background 85ms ease-out, color 85ms ease-out;
  }

  [data-slot="autocomplete-clear"]:hover:not([data-disabled]),
  [data-slot="autocomplete-trigger"]:hover:not([data-disabled]) {
    background: var(--v2-overlay-simple-overlay-hover);
    color: var(--v2-icon-icon-base);
  }

  [data-slot="autocomplete-clear"]:active:not([data-disabled]),
  [data-slot="autocomplete-trigger"]:active:not([data-disabled]) {
    background: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="autocomplete-clear"]:focus-visible,
  [data-slot="autocomplete-trigger"]:focus-visible {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: 1px;
  }

  [data-slot="autocomplete-clear"][data-disabled],
  [data-slot="autocomplete-trigger"][data-disabled] {
    cursor: not-allowed;
    pointer-events: none;
    opacity: 0.5;
  }

  [data-slot="autocomplete-clear"] svg,
  [data-slot="autocomplete-trigger"] svg {
    display: block;
    flex: none;
  }

  [data-slot="autocomplete-trigger"] [data-slot="autocomplete-chevron"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transform: rotate(180deg);
    transition: transform 120ms ease-out;
  }

  [data-slot="autocomplete-trigger"][data-open] [data-slot="autocomplete-chevron"] {
    transform: rotate(0deg);
  }

  /* ---------------------------------------------------------------- */
  /* Floating content popup (mirrors select.css / menu.css)           */
  /* ---------------------------------------------------------------- */

  [data-slot="autocomplete-content"] {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    margin: 0;
    padding: 4px;
    border: 0;
    min-width: max(160px, var(--anchor-width, 0px));
    max-width: min(24rem, var(--available-width, 24rem));
    max-height: min(16rem, var(--available-height, 16rem));
    z-index: 60;
    pointer-events: auto;
    overflow: hidden;

    background: var(--v2-background-bg-layer-01);
    border-radius: 6px;
    box-shadow: var(--v2-elevation-floating);
    outline: none;

    transform-origin: var(--transform-origin, top center);
    transition:
      opacity 120ms ease-out,
      transform 120ms ease-out;

    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: geometricPrecision;
  }

  [data-slot="autocomplete-content"][data-starting-style],
  [data-slot="autocomplete-content"][data-ending-style] {
    opacity: 0;
    transform: scale(0.97);
  }

  [data-slot="autocomplete-list"] {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    gap: 1px;
    outline: none;
  }

  [data-slot="autocomplete-list"][aria-busy="true"] {
    opacity: 0.6;
  }

  /* ---------------------------------------------------------------- */
  /* Items                                                            */
  /* ---------------------------------------------------------------- */

  [data-slot="autocomplete-item"] {
    box-sizing: border-box;
    display: flex;
    flex-shrink: 0;
    flex-direction: row;
    align-items: center;
    gap: 8px;
    min-height: 28px;
    padding: 4px 8px;
    background: transparent;
    border-radius: 4px;
    outline: none;
    cursor: default;
    user-select: none;
    text-decoration: none;

    font-size: 13px;
    font-weight: 440;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
    font-variation-settings: "slnt" 0;
    font-variant-numeric: tabular-nums;
    color: var(--v2-text-text-base);
  }

  [data-slot="autocomplete-item"][data-highlighted] {
    background: var(--v2-overlay-simple-overlay-hover);
  }

  [data-slot="autocomplete-content"][data-modality="keyboard"]
    [data-slot="autocomplete-item"][data-highlighted] {
    background: var(--v2-overlay-simple-overlay-hover);
    outline: 1px solid var(--v2-border-border-focus);
    outline-offset: -1px;
  }

  [data-slot="autocomplete-item"][data-disabled] {
    pointer-events: none;
    opacity: 0.5;
  }

  [data-slot="autocomplete-item-icon"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    width: 16px;
    height: 16px;
    color: var(--v2-icon-icon-muted);
  }

  [data-slot="autocomplete-item"][data-highlighted] [data-slot="autocomplete-item-icon"] {
    color: var(--v2-icon-icon-base);
  }

  [data-slot="autocomplete-item-icon"] svg {
    display: block;
    width: 14px;
    height: 14px;
  }

  :dir(rtl) [data-slot="autocomplete-item-icon"][data-mirror] {
    transform: scaleX(-1);
  }

  [data-slot="autocomplete-item-text"] {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-slot="autocomplete-item-text"] mark {
    background: var(--v2-state-bg-info);
    color: var(--v2-state-fg-info);
    font-weight: 530;
    border-radius: 2px;
    padding: 0 1px;
  }

  /* ---------------------------------------------------------------- */
  /* Groups, separators, empty, status                                */
  /* ---------------------------------------------------------------- */

  [data-slot="autocomplete-group"] {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 1px;
  }

  [data-slot="autocomplete-group-label"] {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    height: 24px;
    padding: 0 8px;
    font-size: 11px;
    font-weight: 530;
    letter-spacing: 0.05px;
    color: var(--v2-text-text-faint);
    user-select: none;
    font-variant-numeric: tabular-nums;
  }

  [data-slot="autocomplete-separator"] {
    flex: none;
    height: 1px;
    width: calc(100% + 4px);
    margin: 3px -2px;
    background: var(--v2-border-border-muted);
    border: none;
  }

  [data-slot="autocomplete-empty"]:not(:empty) {
    padding: 12px 8px;
    text-align: center;
    font-size: 12px;
    font-weight: 440;
    line-height: 16px;
    color: var(--v2-text-text-faint);
    user-select: none;
  }

  [data-slot="autocomplete-status"] {
    padding: 4px 8px;
    font-size: 11px;
    font-weight: 530;
    line-height: 14px;
    letter-spacing: 0.04px;
    color: var(--v2-text-text-faint);
    font-variant-numeric: tabular-nums;
    user-select: none;
  }

  [data-slot="autocomplete-status"]:empty {
    display: none;
  }

  [data-slot="autocomplete-arrow"] {
    width: 8px;
    height: 8px;
    background: var(--v2-background-bg-layer-01);
    transform: rotate(45deg);
    box-shadow: var(--v2-elevation-elements);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="autocomplete-control"],
    [data-slot="autocomplete-input"],
    [data-slot="autocomplete-clear"],
    [data-slot="autocomplete-trigger"],
    [data-slot="autocomplete-trigger"] [data-slot="autocomplete-chevron"],
    [data-slot="autocomplete-content"] {
      transition: none;
    }
  }
}
